#!/usr/bin/env python3
"""Install the custom Smalta switch/button artwork and animations.

Put this script next to config.py in the SmaltaSimPygame project root and run:
    python install_smalta_switch_animations.py
Existing controls/thumbler.py and controls/big_button.py are backed up.
"""
from pathlib import Path
import base64

PAYLOADS = {'controls/icon_animation.py': '', 'controls/thumbler.py': '', 'controls/big_button.py': '', 'assets/Smalta/Controls/button_on.png': '', 'assets/Smalta/Controls/button_off.png': '', 'assets/Smalta/Controls/lever_ball_red.png': '', 'assets/Smalta/Controls/lever_ivory.png': '', 'assets/Smalta/Controls/lever_small_toggle.png': '', 'assets/Smalta/Controls/lever_tall_red.png': '', 'assets/Smalta/Controls/lever_tall_white.png': ''}


def locate_root() -> Path:
    here = Path(__file__).resolve().parent
    for path in (here, *here.parents):
        if (path / "config.py").is_file() and (path / "controls").is_dir():
            return path
    raise FileNotFoundError(
        "Project root not found. Put this installer beside config.py and controls/."
    )


def main() -> int:
    try:
        root = locate_root()
    except FileNotFoundError as exc:
        print(f"ERROR: {exc}")
        return 2

    print(f"Project: {root}")
    for relative, encoded in PAYLOADS.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists() and target.suffix == ".py":
            backup = target.with_suffix(target.suffix + ".before_smalta_icons.bak")
            if not backup.exists():
                backup.write_bytes(target.read_bytes())
                print(f"Backup: {backup.relative_to(root)}")
        target.write_bytes(base64.b64decode(encoded))
        print(f"Installed: {relative}")

    print("\nFinished. Coordinates, smalta.py, config.py and algorithms were not changed.")
    print("Start the app with: python main.py")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
